// ─── EDIT THESE TWO CONSTANTS, THEN NEVER AGAIN ──────────────────────────────
const PROD_BASE = 'https://example.com';
const STAGING_BASE = 'https://staging.example.com';
// ─────────────────────────────────────────────────────────────────────────────
// Both environment bases live in ONE node on purpose. Two hardcoded literals in
// two different nodes drift apart the first time someone renames a staging host,
// and the workflow then quietly compares production against production and
// reports a beautifully clean 0% every night.

// A trailing slash on the base plus a leading slash on the path yields
// "https://host//pricing". Some servers 301 that to the single-slash form, some
// serve it as a different page — so normalise both ends before joining.
const normaliseBase = (base) => String(base || '').trim().replace(/\/+$/, '');
const normalisePath = (path) => {
  const raw = String(path || '').trim();
  if (!raw || raw === '/') return '/';
  return ('/' + raw.replace(/^\/+/, '')).replace(/\/{2,}/g, '/');
};

const prodBase = normaliseBase(PROD_BASE);
const stagingBase = normaliseBase(STAGING_BASE);

// The API rejects a bare domain with the soft error `Url must match format "uri"`
// (HTTP 200 with { error: true, message }). Detect it here so the digest can name
// WHICH constant is wrong instead of repeating a generic API message once per path.
const baseProblems = [];
if (!/^https:\/\//i.test(prodBase)) {
  baseProblems.push(`PROD_BASE must start with https:// (got "${PROD_BASE}")`);
}
if (!/^https:\/\//i.test(stagingBase)) {
  baseProblems.push(`STAGING_BASE must start with https:// (got "${STAGING_BASE}")`);
}

return $input.all().map((item) => {
  const row = item.json;
  const path = normalisePath(row.path);
  const problems = [...baseProblems];
  if (!row.path) {
    problems.push('Sheet row has no `path` value — check that cell A1 literally says `path`.');
  }

  return {
    json: {
      label: row.label || path,
      path,
      productionUrl: prodBase + path,
      stagingUrl: stagingBase + path,
      configError: problems.length ? problems.join(' · ') : '',
    },
  };
});

// ─── Drift bands, not a boolean ──────────────────────────────────────────────
// A nightly staging diff is never zero: staging is legitimately ahead of
// production most nights. A flat changed/unchanged gate would therefore fire
// every single night, and a nightly alert that always fires is muted within a
// week. So every path is bucketed instead, and only the top two bands count as
// actionable. Thresholds are percentages of the page (0–100), matching
// summary.mismatchPercentage.
const MINOR_DRIFT_PCT = 0.01;      // a one-character text change measures ~0.01% (146 px of 1,296,000, live-tested)
const SIGNIFICANT_DRIFT_PCT = 10;  // layout drift — a block moved, spacing or a font changed
const SEVERE_DRIFT_PCT = 30;       // gross breakage — missing stylesheet, whole section absent

const bandFor = (pct) => {
  if (pct >= SEVERE_DRIFT_PCT) return 'severe';
  if (pct >= SIGNIFICANT_DRIFT_PCT) return 'significant';
  if (pct >= MINOR_DRIFT_PCT) return 'minor';
  return 'identical';
};

// batchSize is 1, so the row for this iteration is the single item the URL-pair
// node emitted. .first(), not .item — a Code node running once for all items has
// no per-item linking context.
const pair = $('Build Environment URL Pair').first().json;

return $input.all().map((item) => {
  const res = item.json;
  const summary = res.summary || {};
  const pct = Number(summary.mismatchPercentage ?? 0);

  return {
    json: {
      status: 'compared',
      label: pair.label,
      path: pair.path,
      productionUrl: (res.before && res.before.source) || pair.productionUrl,
      stagingUrl: (res.after && res.after.source) || pair.stagingUrl,
      // Raw 0–100 percentage, never rounded: toFixed(1) renders a real 0.01%
      // text change as a dismissible "0.0%".
      mismatchPercentage: pct,
      mismatchPixels: summary.mismatchPixels ?? null,
      // Only an explicit false counts as a height difference — a missing field
      // must not manufacture an alarm.
      sameDimensions: summary.sameDimensions !== false,
      productionHeight: (res.before && res.before.height) ?? null,
      stagingHeight: (res.after && res.after.height) ?? null,
      diffLink: (res.diff && res.diff.link) || '',
      beforeLink: (res.before && res.before.link) || '',
      afterLink: (res.after && res.after.link) || '',
      band: bandFor(pct),
      message: '',
    },
  };
});

// One message per night, sorted worst-first so the top line is the first thing
// read at standup. Band names come from Record Drift Result — the thresholds live
// there and only there, so the two nodes can never disagree about a band.
const rows = $input.all().map((item) => item.json);

const compared = rows
  .filter((r) => r.status === 'compared')
  .sort((a, b) => Number(b.mismatchPercentage) - Number(a.mismatchPercentage));
const failed = rows.filter((r) => r.status === 'failed');

const inBand = (band) => compared.filter((r) => r.band === band);
const severe = inBand('severe');
const significant = inBand('significant');
const minor = inBand('minor');
const identical = inBand('identical');

// Differing page heights between environments almost always mean a whole block
// exists on one side only — the most actionable single finding in the report.
const heightDrift = compared.filter((r) => r.sameDimensions === false);

const MINOR_LINES_SHOWN = 10; // Slack caps a message near 40,000 characters.

const link = (r) => `<${r.stagingUrl}|${r.label}>`;
const line = (r) =>
  `• ${link(r)} — ${r.mismatchPercentage}%${r.diffLink ? ` · <${r.diffLink}|diff>` : ''}`;

const lines = [];
lines.push(`*Staging drift — nightly report* · ${rows.length} paths · staging vs production (both live)`);
lines.push(
  `🔴 ${severe.length} severe · 🟠 ${significant.length} significant · 🟡 ${minor.length} minor · ⚪ ${identical.length} identical · ⚠️ ${failed.length} failed`
);

if (severe.length) {
  lines.push('');
  lines.push('*Severe drift* — gross breakage territory (missing CSS, whole section absent)');
  severe.forEach((r) => lines.push(line(r)));
}

if (significant.length) {
  lines.push('');
  lines.push('*Significant drift* — layout moved');
  significant.forEach((r) => lines.push(line(r)));
}

if (minor.length) {
  lines.push('');
  lines.push('*Minor drift* — copy or small styling changes, usually staging legitimately ahead');
  minor.slice(0, MINOR_LINES_SHOWN).forEach((r) => lines.push(line(r)));
  if (minor.length > MINOR_LINES_SHOWN) {
    lines.push(`• …and ${minor.length - MINOR_LINES_SHOWN} more minor paths`);
  }
}

if (heightDrift.length) {
  lines.push('');
  lines.push('*Page height differs between environments* — a block probably exists on one side only');
  heightDrift.forEach((r) =>
    lines.push(`• ${link(r)} — production ${r.productionHeight ?? '?'}px vs staging ${r.stagingHeight ?? '?'}px`)
  );
}

if (failed.length) {
  lines.push('');
  lines.push('*Could not be compared*');
  failed.forEach((r) => lines.push(`• ${link(r)} — ${r.message || 'unknown error'}`));
}

const top = compared[0] || null;

return [
  {
    json: {
      digest: lines.join('\n'),
      // Actionable = worth a human's attention tonight. Minor drift deliberately
      // does NOT trigger the digest branch on its own.
      actionableCount: severe.length + significant.length + failed.length,
      severeCount: severe.length,
      significantCount: significant.length,
      minorCount: minor.length,
      identicalCount: identical.length,
      failedCount: failed.length,
      heightDriftCount: heightDrift.length,
      totalCount: rows.length,
      topLabel: top ? top.label : 'n/a',
      topMismatch: top ? top.mismatchPercentage : 0,
    },
  },
];
